describe('Payment Flow - Card Declined Error', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="payment-form"]').should('be.visible');
  });

  it('should display error message when card is declined', () => {
    cy.get('[data-testid="card-number-input"]').type('4000000000000002');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="cardholder-name-input"]').type('John Doe');

    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="error-message"]', { timeout: 10000 })
      .should('be.visible')
      .and('contain', 'Your card was declined');

    cy.get('[data-testid="error-icon"]').should('be.visible');
    cy.get('[data-testid="card-number-input"]').should('have.class', 'error-state');
  });

  it('should allow user to retry payment after card decline', () => {
    cy.get('[data-testid="card-number-input"]').type('4000000000000002');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="cardholder-name-input"]').type('Jane Smith');

    cy.get('[data-testid="submit-payment-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');

    cy.get('[data-testid="card-number-input"]').clear().type('4242424242424242');
    cy.get('[data-testid="error-message"]').should('not.exist');

    cy.get('[data-testid="submit-payment-btn"]').click();
    cy.get('[data-testid="success-message"]', { timeout: 10000 })
      .should('be.visible')
      .and('contain', 'Payment successful');
  });

  it('should display specific error for expired card', () => {
    cy.get('[data-testid="card-number-input"]').type('4000000000000069');
    cy.get('[data-testid="card-expiry-input"]').type('01/20');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="cardholder-name-input"]').type('Test User');

    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="error-message"]', { timeout: 10000 })
      .should('be.visible')
      .and('contain', 'Your card has expired');
  });

  it('should display error for insufficient funds', () => {
    cy.get('[data-testid="card-number-input"]').type('4000000000000077');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="cardholder-name-input"]').type('Low Balance User');

    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="error-message"]', { timeout: 10000 })
      .should('be.visible')
      .and('contain', 'Insufficient funds');
  });

  it('should persist error state and allow form correction', () => {
    cy.get('[data-testid="card-number-input"]').type('4000000000000002');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="cardholder-name-input"]').type('Error Test');

    cy.get('[data-testid="submit-payment-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');

    cy.get('[data-testid="card-number-input"]').should('have.value', '4000000000000002');
    cy.get('[data-testid="cardholder-name-input"]').should('have.value', 'Error Test');

    cy.get('[data-testid="card-number-input"]').clear().type('4242424242424242');
    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="success-message"]', { timeout: 10000 }).should('be.visible');
  });
});
